import type { EdgeProps } from '../../types';
import { BaseEdge } from './BaseEdge';
import { getSmartBezierPath } from '../../utils/path';

export function BezierEdge({ sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition, selected, animated, label, style }: EdgeProps) {
  const path = getSmartBezierPath(
    { x: sourceX, y: sourceY },
    { x: targetX, y: targetY },
    sourcePosition,
    targetPosition,
  );
  const labelX = (sourceX + targetX) / 2;
  const labelY = (sourceY + targetY) / 2;

  return <BaseEdge path={path} selected={selected} animated={animated} label={label} labelX={labelX} labelY={labelY} style={style} />;
}
